Ltac nodisj := repeat match goal with H : _ \/ _ |- _ => clear H end.
Ltac dlia := first [ solve [ L5FastLia.prune_arith; nodisj; L5FastLia.lia_ne ]
                   | solve [ L5FastLia.prune_arith; match goal with H : _ \/ _ |- _ => L5SAR.clear_disj_but H; destruct H; L5FastLia.lia_ne end ]
                   | solve [ L5FastLia.prune_arith; nodisj; L5FastLia.lia_st ]
                   | solve [ L5FastLia.prune_arith; match goal with H : _ \/ _ |- _ => L5SAR.clear_disj_but H; destruct H; L5FastLia.lia_st end ] ].
Local Ltac lia := dlia.
Module PMBSLSG2.
Ltac inl := apply L5K.In_of_mem; vm_compute; reflexivity.
Ltac amod := match goal with H : ?x mod ?m = 0 |- ?x mod ?m = 0 => exact H end.
Ltac ftac := lazymatch goal with |- PMBSLSP1.aligned _ _ => unfold PMBSLSP1.aligned; first [amod | lia] | |- PMBSLSP5.aligned _ _ => unfold PMBSLSP5.aligned; first [amod | lia] end.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Abbreviation RSEGS := AsanUbsan.M.loaded_segments.
Abbreviation st fx R pc M := (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)).

Section Stage.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (HI : asan_iface).
Hypothesis LY : PMB.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Hypothesis EXT : HAJ.asan_ext_ok L ar SCFG HI PMB.EXT.
Let LYa := PMB.ly_as0 L C LY.

Theorem grow2 : PMB.opdel_spec L ar HI -> forall (fx6 : FPState) R M model K LBX FF LK Aw cr v b k stk sp r p1 p2 m n B R6 M6 model6 Aw6,
    ri_inv HI (PM.vec_own b k ++ LBX) FF LK cr Aw M (vml_of model) -> K [] -> PMSPA.entryA PeCLayoutB.CADDR_B L ar R M sp r 0 ->
    PMSPA.aobjA FF v 24 -> v mod 8 = 0 -> Z.of_nat (length stk) = 2 ^ k -> 0 <= k <= 10 -> 0 <= p1 < 2 ^ 47 -> 0 <= p2 < 2 ^ 47 ->
    PMBSLSGS.gmid L ar HI R M model LBX FF LK Aw cr v b k stk sp p1 p2 m n B R6 M6 model6 Aw6 ->
    (forall (fx' : FPState) R' M' model' LK' Aw' b', regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 (b' + 32 * 2 ^ k + 32) ->
        PM.vec_at RSEGS PMSPA.accA PMSPA.annA M' v b' (k + 1) (stk ++ [PM.PS m n 0 0]) ->
        PMSPA.accA M' v 24 -> L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr 0) [(v, 24)] M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vec_own b' (k + 1) ++ LBX) FF LK' (adebit L cr (32 * 2 ^ (k + 1))) Aw' M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx' R' r M' model') K) ->
    srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx6 R6 0xb5880 M6 model6) K.
Proof.
